  def is_empty(self):
    return self.front == -1

  def is_full(self):
    return (self.rear + 1) % self.capacity == self.front

from math import gcd


class PollardsRhoFactorization:
    """Performs integer factorization using Pollard's Rho algorithm."""

    def __init__(self, n: int):
        self.n = n

    def pollards_rho_polynomial(self, x: int):
        return (x * x + 1) % self.n

    def pollards_rho_factorization(self):
        if self.n == 1:
            return None

        x, y, d = 2, 2, 1
        while d == 1:
            x = self.pollards_rho_polynomial(x)
            y = self.pollards_rho_polynomial(y)
            d = gcd(abs(x - y), self.n)
        if d == self.n:
            return None
        return d

from typing import Literal, List

Token = Literal["expr", ";", "if", "(", ")", "other"]
NonTerminal = Literal["stmt"]


class ParseTree:
    def __init__(self, children, nonterminal: NonTerminal):
        self.children = children
        self.nonterminal = nonterminal

    def __eq__(self, obj) -> bool:
        if not isinstance(obj, ParseTree):
            return False
        if isinstance(obj, ParseTree) and obj.nonterminal != self.nonterminal:
            return False
        else:
            if len(self.children) != len(obj.children):
                return False
            else:
                for i, child in enumerate(obj.children):
                    if child != self.children[i]:
                        return False
            return True


class Parser:
    Malformed = ValueError("input is not in the language accepted by this grammar")

    def __init__(self):
        self.inputs = []
        self.lookahead = 0

    def parse(self, inputs: List[Token]) -> ParseTree:
        self.inputs = inputs
        self.lookahead = 0
        temp = self.stmt()
        if self.lookahead != len(self.inputs):
            raise Parser.Malformed
        else:
            return temp

    def match(self, terminal: Token):
        if terminal == self.inputs[self.lookahead]:
            self.lookahead += 1
        else:
            raise Parser.Malformed

    def stmt(self) -> ParseTree:
        match self.inputs[self.lookahead]:
            case "expr":
                self.match("expr")
                self.match(";")
                return ParseTree(["expr", ";"], "stmt")
            case "if":
                self.match("if")
                self.match("(")
                self.match("expr")
                self.match(")")
                return ParseTree(["if", "(", "expr", ")", self.stmt()], "stmt")
            case "other":
                self.match("other")
                return ParseTree(["other"], "stmt")
            case _:
                raise Parser.Malformed

import numpy as np
import pandas as pd
from scipy.cluster.hierarchy import linkage, fcluster
from scipy.spatial.distance import squareform


class FeatureSelector:
  """Selects features from a set of data according to their correlations"""

  def __init__(self, data: pd.DataFrame, columns: list[str]):
    self.data = data
    self.columns = columns

  def corr_matrix(self):
    features = self.data[self.columns]
    return features.corr()

  def cluster(self, threshold):
    corr = self.corr_matrix()
    dissimilarity = 1 - abs(corr)
    for i in range(1, len(corr)):
      dissimilarity.iloc[i, i] = 0
    Z = linkage(squareform(dissimilarity.values), 'complete')
    labels = fcluster(Z, threshold, criterion='distance')
    clusters = {}
    for c, l in zip(self.columns, labels):
      if l in clusters:
        clusters[l].append(c)
      else:
        clusters[l] = [c]
    return list(clusters.values())

  def select_features(self, clusters):
    return [c[0] for c in clusters]

from math import gcd


class PollardsRhoFactorization:
  """Performs integer factorization using Pollard's Rho algorithm."""

  def __init__(self, n: int):
    self.n = n

  def pollards_rho_polynomial(self, x: int):
    return (x * x + 1) % self.n

  def pollards_rho_factorization(self):
    if self.n == 1:
      return None

    x, y, d = 2, 2, 1
    while d == 1:
      x = self.pollards_rho_polynomial(x)
      y = self.pollards_rho_polynomial(y)
      d = gcd(abs(x - y), self.n)
    if d == self.n:
      return None
    return d

from typing import List, Literal


class Semver:
    def __init__(self, major: int, minor: int, patch: int):
        self.major = major
        self.minor = minor
        self.patch = patch

    def __str__(self):
        return f'{self.major}.{self.minor}.{self.patch}'

    def __eq__(self, other):
        return self.major == other.major and \
            self.minor == other.minor and \
            self.patch == other.patch

    def __lt__(self, other):
        if self.major < other.major:
            return True
        elif self.major == other.major:
            if self.minor < other.minor:
                return True
            elif self.minor == other.minor:
                return self.patch < other.patch
        return False

    def __gt__(self, other):
        if self.major > other.major:
            return True
        elif self.major == other.major:
            if self.minor > other.minor:
                return True
            elif self.minor == other.minor:
                return self.patch > other.patch
        return False

    def __le__(self, other):
        return self < other or self == other

    def __ge__(self, other):
        return self > other or self == other

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))


class PackageVersion:
    def __init__(self, version: Semver, dependencies: List["SemverConstraint"] = []):
        self.version = version
        self.dependencies = dependencies


class Package:
    def __init__(self, name: str, versions: List[PackageVersion]):
        self.name = name
        self.versions = versions

    def max_satisfying_version(self, constraints: List["SemverConstraint"]):
        max_version = None
        for version in self.versions:
            if all([constraint.satisfies(version.version) for constraint in constraints]):
                if max_version is None or version.version > max_version.version:
                    max_version = version
        return max_version


class SemverConstraint:
    def __init__(
        self,
        package: str,
        constraint: Literal["==", ">=", "<=", ">", "<"],
        version: Semver,
    ):
        self.package = package
        assert constraint in ["==", ">=", "<=", ">", "<"], \
            f'Constraint must be one of "==", ">=", "<=", ">", "<", not {constraint}'
        self.constraint = constraint
        self.version = version

    def __str__(self):
        return f'{self.package} {self.constraint} {self.version}'

    def satisfies(self, version: Semver):
        if self.constraint == "==":
            return version == self.version
        elif self.constraint == ">=":
            return version >= self.version
        elif self.constraint == "<=":
            return version <= self.version
        elif self.constraint == ">":
            return version > self.version
        elif self.constraint == "<":
            return version < self.version

