class Quiz:

  def __init__(self, questions, answers):
    self.questions = questions
    self.answers = answers
    self.total_questions = len(questions)
    self.score = 0
    self.current_question = 0

  def check_answer(self, question_index, answer) -> bool:
    if self.answers[question_index] == answer:
      self.score += 1
      return True
    return False

  def next_question(self):
    if self.current_question == self.total_questions:
      raise IndexError("No more questions!")
    else:
      q = self.questions[self.current_question]
      self.current_question += 1
      return q

  def add_question(self, question, answer):
    self.questions.append(question)
    self.answers.append(answer)
    self.total_questions += 1

  def display_results(self):
    return f"Total Questions: {self.total_questions}\nTotal Points Obtained: {self.score}"

import math

def permutation(n, r):
    return int(math.factorial(n) / math.factorial(n - r))

def combination(n, r):
    return int(math.factorial(n) / (math.factorial(r) * math.factorial(n - r)))

def arrangement_unlimited_rep(n, r):
    return int(n ** r)


def combination_unlimited_rep(n, r):
    return int(combination(n + r - 1, r))

def arrangement_restricted_rep(n, rList):
    product = 1

    for r in rList:
        product *= math.factorial(r)

    return int(math.factorial(n) / product)

from typing import Literal, List

Input = Literal["a", "b", ""]
State = Literal[0, 1, 2]


class NFA:
    def __init__(self) -> None:
        self.current: State = 0
        self.accept: set[State] = {1, 2}

    def transition(self, input: Input) -> List[State]:
        table = {
            0: {"a": [1, 2], "b": [], "": [0]},
            1: {"a": [], "b": [], "": [1]},
            2: {"a": [], "b": [2], "": [2]},
        }
        return table[self.current][input]

    def accepted(self):
        return self.current in self.accept

import ast


class UsageCounter(ast.NodeVisitor):
  """
    Counts the usages of each identifier in the given AST.
    An usage does not count the definition or assignment itself;
    only identifiers that are used after their definition/assignment are counted.
    NOTE: This class does not handle the scoping rules of Python;
    it simply counts the usages based on the name of the identifiers.
    It also only supports identifiers defined in either a function or assignment operation.
    """

  def __init__(self):
    self.usages = {}

  def visit_Name(self, node):
    if node.id in self.usages:
      self.usages[node.id] += 1
      self.generic_visit(node)

  def visit_FunctionDef(self, node):
    if node.name not in self.usages:
      self.usages[node.name] = 0
    self.generic_visit(node)

  def visit_Assign(self, node):
    id_defined = None
    for target in node.targets:
      if isinstance(target, ast.Name):
        if target.id not in self.usages:
          self.usages[target.id] = 0
        id_defined = target.id

    self.generic_visit(node)
    if id_defined is not None:
      self.usages[id_defined] -= 1

def gcd(a, b):
    return a if b == 0 else gcd(a % b, b)

def lcm(a, b):
    return (a * b) / gcd(a, b)

from typing import List


class Node:
    '''Simple node (No duplicate edges between nodes)'''

    def __init__(self, id: int):
        self.id = id
        self.out_edges = []
        self.in_edges = []

    def __eq__(self, __value: object) -> bool:
        if not isinstance(__value, Node):
            return False
        else:
            return self.id == __value.id

    def __hash__(self) -> int:
        return self.id


class Edge:
    def __init__(self, src: Node, dest: Node, weight: int):
        assert weight > 0
        assert src == dest

        self.src = src
        self.dest = dest
        self.weight = weight

    def __eq__(self, __value: object) -> bool:
        if not isinstance(__value, Edge):
            return False
        else:
            return self.dest == __value.dest and self.src == __value.src


class Graph:
    '''Simple directed graph (No duplicate edges between nodes, no duplicate nodes)'''

    def __init__(self, nodes: List[Node]):
        uniques = {}
        for node in nodes:
            if node in uniques.keys():
                raise RuntimeError
            else:
                uniques[node] = True
        self.nodes = nodes
        self.edges = []

    def add_edge(self, edge: Edge):
        assert edge not in self.edges
        self.edges.append(edge)

import math


def mean(data):
  runningSum = 0
  for val in data:
    runningSum += val
  return runningSum / len(data)


def calculate_range(data):
  dataSorted = sorted(data)
  return dataSorted[-1] - dataSorted[0]


def mode(data):
  freq_dict = {}
  for val in data:
    if val not in freq_dict:
      freq_dict[val] = 0
    freq_dict[val] += 1

  max_freq = max(freq_dict.values())
  modes = [val for val in freq_dict if freq_dict[val] == max_freq]

  return modes


def median(data):
  sorted_data = sorted(data)

  if len(sorted_data) % 2 == 0:
    middleNum1 = sorted_data[len(sorted_data) // 2]
    middleNum2 = sorted_data[(len(sorted_data) // 2) - 1]
    return (middleNum1 + middleNum2) / 2
  else:
    return sorted_data[len(sorted_data) // 2]


def quartile(data):
  if len(data) < 2:
    return data

  sorted_data = sorted(data)
  midpoint = len(sorted_data) // 2

  q1 = median(sorted_data[:midpoint])
  q3 = median(sorted_data[midpoint:])

  q1_data = []
  q2_data = []
  q3_data = []

  quartiles = [q1_data, q2_data, q3_data]

  for val in sorted_data:
    if val < q1:
      q1_data += [val]
    elif val > q1 and val < q3:
      q2_data += [val]
    elif val > q3:
      q3_data += [val]

  return quartiles

