from math import gcd


class PollardsRhoFactorization:
  """Performs integer factorization using Pollard's Rho algorithm."""

  def __init__(self, n: int):
    self.n = n

  def pollards_rho_polynomial(self, x: int):
    return (x * x + 1) % self.n

  def pollards_rho_factorization(self):
    if self.n == 1:
      return None

    x, y, d = 2, 2, 1
    while d == 1:
      x = self.pollards_rho_polynomial(x)
      y = self.pollards_rho_polynomial(y)
      d = gcd(abs(x - y), self.n)
    if d == self.n:
      return None
    return d

class Sorter:

  def __init__(self):
    pass

  def sort(self, nums: list[int]) -> list[int]:
    if len(nums) == 0:
      return nums
    else:
      return self.insert(self.sort(nums[1:]), nums[0])

  def insert(self, nums: list[int], num: int) -> list[int]:
    output = []
    for i, n in enumerate(nums):
      if num < n:
        output.append(num)
        return output + nums[i:]
      else:
        output.append(n)
    return output + [num]

class Comparators:
  """
    A class for that allows for custom comparator actions that work in conjuction with Python's default sorted function
    Example usage: `sorted(lorem_ipsum, key=Comparators.by_length)`
    """

  def by_length(obj):
    """Comparing by length of object"""
    return len(obj)

  def by_num_vowels(obj):
    """Comparing by the number of vowels"""
    vowels = "aeiou"
    return sum(1 for char in obj if char.lower() in vowels)

  def by_numerical_value(obj):
    """Comparing by the numerical value of the object"""
    return obj

  def by_word_count(obj):
    """Comparison by the number of words in the object"""
    return len(obj.split())

def find_primes(end: int):

  primes = []
  is_prime = [True] * (end + 1)

  for num in range(1, int(end**0.5) + 1):
    if is_prime[num]:
      primes.append(num)
      for multiple in range(num * num, end + 1, num):
        is_prime[multiple] = False

  for num in range(int(end**0.5) + 1, end + 1):
    if is_prime[num]:
      primes.append(num)

  return primes

def gcd(a, b):
  return a if b == 0 else gcd(a % b, b)


def lcm(a, b):
  return (a * b) / gcd(a, b)

