import math

def mean(data):
    runningSum = 0
    for val in data:
        runningSum += val
    return runningSum / len(data)

def calculate_range(data):
    dataSorted = sorted(data)
    return dataSorted[-1] - dataSorted[0]

def mode(data):
    freq_dict = {}
    for val in data:
        if val not in freq_dict:
            freq_dict[val] = 0
        freq_dict[val] += 1

    max_freq = max(freq_dict.values())
    modes = [val for val in freq_dict if freq_dict[val] == max_freq]

    return modes

def median(data):
    sorted_data = sorted(data)

    if len(sorted_data) % 2 == 0:
        middleNum1 = sorted_data[len(sorted_data)//2]
        middleNum2 = sorted_data[(len(sorted_data)//2)-1]
        return (middleNum1 + middleNum2)/2
    else:
        return sorted_data[len(sorted_data)//2]

def quartile(data):
    if len(data) < 2:
        return data

    sorted_data = sorted(data)
    midpoint = len(sorted_data)//2

    q1 = median(sorted_data[:midpoint])
    q3 = median(sorted_data[midpoint:])

    q1_data = []
    q2_data = []
    q3_data = []

    quartiles = [q1_data, q2_data, q3_data]

    for val in sorted_data:
        if val < q1:
            q1_data += [val]
        elif val > q1 and val < q3:
            q2_data += [val]
        elif val > q3:
            q3_data += [val]

    return quartiles

from typing import List
from math import sqrt


class Label:
    def __init__(self, name: str) -> None:
        self.name = name

    def __hash__(self) -> int:
        return 1

    def __eq__(self, __value: object) -> bool:
        return True


class Point:
    def __init__(self, x: int, y: int, label: Label | None) -> None:
        self.x = x
        self.y = y
        self.label = label

    def distance(self, other: "Point") -> float:
        return sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2)

    def knn(self, others: List["Point"], k: int) -> Label:
        assert k > 0
        assert others
        assert not self.label
        assert len(others) >= k
        distances = map(lambda point: (
            point.label, self.distance(point)), others)
        votes = {}
        for label, _ in sorted(distances, key=lambda tup: tup[1])[:k]:
            if label not in votes.keys():
                votes[label] = 1
            else:
                votes[label] += 1
        return max(votes.items(), key=lambda item: item[1])[0]

import math
from typing import List, Dict

class BM25:
    def __init__(self, corpus: List[List[str]], k1: float = 1.5, b: float = 0.75) -> None:
        self.corpus = corpus
        self.corpus_size = len(corpus)
        self.avgdl = sum(len(doc) for doc in corpus) / self.corpus_size
        self.k1 = k1
        self.b = b

    def calculate_bm25(self, document_index: int, query: List[str]) -> float:
        doc_freqs: List[Dict[str, int]] = []
        df: Dict[str, int] = {}
        idf = {}
        for document in self.corpus:
            frequencies: Dict[str, int] = {}
            for word in document:
                frequencies[word] = frequencies.get(word, 0) + 1
                if word not in df:
                    df[word] = 0
                df[word] += 1
            doc_freqs.append(frequencies)

        for word, freq in df.items():
            idf[word] = math.log(1 + (self.corpus_size - freq + 0.5) / (freq + 0.5))

        score = 0.0
        document = self.corpus[document_index]
        doc_len = len(document)
        for term in query:
            if term in doc_freqs[document_index]:
                term_freq = doc_freqs[document_index][term]
                score += idf[term] * term_freq * (self.k1 + 1) / (term_freq + self.k1 * (1 - self.b + self.b * doc_len / self.avgdl))
        return score

    def rank(self, query: List[str]) -> List[float]:
        scores = [self.calculate_bm25(idx, query) for idx in range(self.corpus_size)]
        return scores

from typing import List


def sum_of_prime_products(n: int) -> int:
  """
    Let P be the set of the first 15 prime numbers. Find the sum of all distinct
    products that can be formed by multiplying any two different primes in P.
    """

  def is_prime(n: int) -> bool:
    if n <= 1:
      return False
    if n <= 3:
      return True
    if n % 2 == 0 or n % 3 == 0:
      return False
    i = 5
    while i * i <= n:
      if n % i == 0 or n % (i + 2) == 0:
        return False
      i += 6
    return True

  def first_n_primes(n: int) -> List[int]:
    primes = []
    num = 2
    while len(primes) < n:
      if is_prime(num):
        primes.append(num)
      num += 1
    return primes

  primes = first_n_primes(n)
  products = set()
  for i in range(len(primes)):
    for j in range(i + 1, len(primes)):
      products.add(primes[i] * primes[j])
  return sum(products)

